    <app-settings [(floors)]="floors" [(latePcts)]="latePcts" [(graces)]="graces" [(policyDate)]="policyDate" [(caps)]="caps" [(pot)]="pot" />
    <app-periods [(periods)]="periods" [dues]="dues()" />
